  &lt;span class="nt"&gt;-p&lt;/span&gt; 8080:8080 &lt;span class="nt"&gt;-p&lt;/span&gt; 8082:8082 &lt;span class="se"&gt;\&lt;/span&gt;
  mcr.microsoft.com/dts/dts-emulator:latest
